function publicDaysAway(n){return n===0?publicText("本日"):publicEnglish?n+(n===1?" day away":" days away"):publicLanguage==="ko"?n+"일 후":publicLanguage==="id"?n+" hari lagi":publicLanguage==="th"?"อีก "+n+" วัน":publicLanguage.startsWith("zh")?n+" 天後".replace("後",publicLanguage==="zh-Hans"?"后":"後"):n+"日後"}
function publicWeekday(date){return new Intl.DateTimeFormat(publicLanguage,{calendar:"gregory",weekday:"short",timeZone:"UTC"}).format(new Date(date+"T00:00:00Z"))}
