 if(!Array.isArray(s.guests)||s.guests.some(g=>!g||typeof g.name!=="string"||!g.name.trim()||typeof g.url!=="string"||g.url&&!scheduleGuestUrl(g.url)))return "外部コラボ相手の活動名・公式リンクを確認してください。";
