 if(member&&["news.html","schedule.html"].includes(page))url.searchParams.set("member",member);
 const href=url.href,heading=String(title||"架空事務所 ぽっぽー").trim();
 target.classList.add("pop-share-panel");target.setAttribute("role","group");target.setAttribute("aria-label",label);
 const titleEl=document.createElement("strong");titleEl.className="pop-share-heading";titleEl.textContent=publicText(label);
 const buttons=document.createElement("div");buttons.className="pop-share-buttons";
 for(const [name,kind,link] of publicShareLinks(href,heading)){
  const a=document.createElement("a");a.className="pop-share-button pop-share-"+kind;a.href=link;a.target="_blank";a.rel="noopener noreferrer";a.referrerPolicy="no-referrer";a.textContent=name;a.setAttribute("aria-label",publicFormat("share",name)??(publicEnglish?"Share via "+name+" (new window)":name+"で共有（新しい画面）"));buttons.append(a);
 }
 const status=document.createElement("p");status.className="pop-share-status";status.setAttribute("role","status");
 const fallback=document.createElement("input");fallback.className="pop-share-url";fallback.type="text";fallback.readOnly=true;fallback.value=href;fallback.hidden=true;fallback.setAttribute("aria-label",publicText("共有用URL"));
 const showFallback=()=>{fallback.hidden=false;fallback.focus();fallback.select();status.textContent=publicText("表示されたURLをコピーしてください。")};
 const copy=document.createElement("button");copy.type="button";copy.className="pop-share-button pop-share-copy";copy.textContent=publicText("URLコピー");
 copy.addEventListener("click",async()=>{try{if(!navigator.clipboard?.writeText){showFallback();return}await navigator.clipboard.writeText(href);status.textContent=publicText("URLをコピーしました。")}catch{showFallback()}});
 buttons.append(copy);
 if(typeof navigator.share==="function"){const native=document.createElement("button");native.type="button";native.className="pop-share-button pop-share-native";native.textContent=publicText("その他の共有");native.addEventListener("click",async()=>{try{await navigator.share({title:heading,url:href});status.textContent=publicText("共有操作が完了しました。")}catch(e){if(e.name!=="AbortError"){status.textContent=publicText("共有できませんでした。URLコピーをご利用ください。")}}});buttons.append(native)}
 target.replaceChildren(titleEl,buttons,status,fallback);
